'use strict';
const $ = id => document.getElementById(id);
const palette = {blue:'#79b5ff',teal:'#61d8d2',green:'#77dbac',violet:'#bca4ff',orange:'#f4bc78',red:'#fa929a',pink:'#f1a0cf',slate:'#aebdd4'};
const names = {overview:'Overview',servers:'Servers',containers:'Containers',alerts:'Alerts',tags:'Tags & Groups',diagnostics:'Diagnostics',settings:'Settings',about:'About / Help',server:'Server details'};
const state = {servers:[],tags:[],labels:[],snapshots:new Map(),alerts:[],coverage:{},scanErrors:{},about:{},route:'overview',serverId:'',tab:'summary',busy:false,filters:{servers:{search:'',tag:'all',status:'all',sort:'name'},containers:{search:'',server:'all',status:'all',sort:'name'},alerts:{severity:'all',server:'all',source:'all'}},serverView:localStorage.getItem('contscope.serverView')||'cards'};
let lastFocus=null,toastTimer,modalEpoch=0;
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json = data => ({headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
async function api(path,options={}) {
 const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});
 if(!response.ok){const text=await response.text();let message;try{message=JSON.parse(text).error}catch{};throw new Error(message||(response.status===401?'Authentication required. Sign in again or reload this tab.':text.trim().slice(0,180))||`Request failed (HTTP ${response.status})`)}
 return response.status===204?null:response.json();
}
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4500)}
function fail(error){$('globalError').textContent=error.message||String(error);$('globalError').hidden=false}
function human(value){if(!Number.isFinite(value)||value<=0)return '—';const units=['B','KiB','MiB','GiB','TiB'];const i=Math.min(4,Math.floor(Math.log(value)/Math.log(1024)));return (value/1024**i).toFixed(i>1?1:0)+' '+units[i]}
const percent=(used,total)=>total>0?Math.min(100,Math.max(0,used*100/total)):null;
const pct=value=>Number.isFinite(value)?value.toFixed(1)+'%':'—';
function badge(text,kind=''){return `<span class="badge ${kind}"><span class="dot"></span>${esc(text)}</span>`}
function button(action,text,id='',kind=''){return `<button type="button" class="${kind}" data-action="${action}" data-id="${esc(id)}">${text}</button>`}
function heading(title,subtitle,action=''){return `<div class="page-head"><div><p class="eyebrow">YOUR INFRASTRUCTURE, CLEARLY</p><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="actions">${action}</div></div>`}
function empty(title,message,action=''){return `<div class="empty"><div class="empty-symbol">◇</div><h2>${esc(title)}</h2><p>${esc(message)}</p>${action}</div>`}
function loading(text='Collecting data…'){return `<div class="empty"><div class="loader"></div><p>${esc(text)}</p></div>`}
function tagsFor(server){return (server.tags||[]).map(id=>state.tags.find(t=>t.id===id)).filter(Boolean)}
function tagChip(tag){return `<span class="tag" style="--tag-color:${palette[tag.color]||palette.slate}"><span class="dot"></span>${esc(tag.name)}</span>`}
function tagBadges(server){return `<div class="tags">${tagsFor(server).map(tagChip).join('')}</div>`}
function statusFor(server){const snap=state.snapshots.get(server.id);return !snap?'pending':snap.online?'online':'offline'}
function statusBadge(server){const status=statusFor(server);return badge(status==='pending'?'Checking':status==='online'?'Online':'Offline',status==='online'?'good':status==='offline'?'critical':'')}
function bar(value,kind=''){const tone=value>=95?'critical':value>=85?'warning':kind;return `<div class="bar ${tone}"><span style="width:${Number.isFinite(value)?value:0}%"></span></div>`}
function resource(label,value,kind){return `<div class="metric"><div class="metric-line"><span>${label}</span><b>${pct(value)}</b></div>${bar(value,kind)}</div>`}
function containerHealth(c){const status=(c.status||'').toLowerCase();return status.includes('unhealthy')?'unhealthy':status.includes('(healthy)')?'healthy':status.includes('health: starting')?'starting':'not configured'}
function containerProblem(c){return containerHealth(c)==='unhealthy'||['restarting','dead'].includes(c.state)||/restarting|dead|exited \([1-9][0-9]*\)/i.test(c.status||'')}
function containerState(c){return c.state||(/restarting/i.test(c.status)?'restarting':/^up/i.test(c.status)?'running':/^exited/i.test(c.status)?'exited':'unknown')}
function allContainers(){return state.servers.flatMap(server=>{const snap=state.snapshots.get(server.id);return snap?.online?(snap.containers||[]).map(c=>({...c,server})):[]})}
function labelFor(c){return state.labels.find(l=>l.serverId===c.server.id&&l.containerName===c.name)||{}}
function serverCard(server){const snap=state.snapshots.get(server.id);const usable=snap?.online;return `<article class="server-card"><div class="card-head"><div class="server-name-row"><span class="server-icon">▤</span><div class="server-identity"><h3>${esc(server.name)}</h3><p>${esc(server.host)}:${server.port}</p></div></div>${statusBadge(server)}</div>${tagBadges(server)}${resource('CPU',usable?snap.cpuPercent:null,'')}${resource('Memory',usable?percent(snap.memoryUsed,snap.memoryTotal):null,'cyan')}${resource('Root disk',usable?percent(snap.diskUsed,snap.diskTotal):null,'green')}${snap&&!snap.online?`<p class="form-note bad">${esc(snap.error||'SSH connection failed')}</p>`:''}<div class="card-footer"><span>◇ ${usable?(snap.containers||[]).length:'—'} containers</span>${button('open-server','View details →',server.id,'quiet')}</div></article>`}
function findings(){return state.servers.flatMap(server=>(state.snapshots.get(server.id)?.findings||[]).filter(f=>f.severity!=='info').map(f=>({...f,server,source:'health',at:state.snapshots.get(server.id).at})))}
function alertRows(){return [...findings(),...state.alerts.map(a=>({id:a.id,title:a.guidance?.category||'Application log error',evidence:a.message,nextStep:a.guidance?.nextStep,server:state.servers.find(s=>s.id===a.serverId)||{id:a.serverId,name:a.serverName},containerId:a.containerId,containerName:a.containerName,severity:'warning',at:a.at,source:'logs',view:'logs'}))].sort((a,b)=>new Date(b.at)-new Date(a.at))}
function attentionRow(f){return `<article class="attention-row"><span class="attention-icon ${f.severity}">!</span><div><h3>${esc(f.title)}</h3><p>${esc(f.server.name)}${f.containerName?' · '+esc(f.containerName):''}</p></div>${button('finding','Inspect →',f.id,'quiet')}</article>`}
function overview(){const snapshots=[...state.snapshots.values()],online=snapshots.filter(s=>s.online).length,offline=snapshots.filter(s=>!s.online).length,containers=allContainers(),problems=containers.filter(containerProblem).length;const stats=[['Servers',state.servers.length,'Registered hosts',''],['Online',online,'SSH connected','good'],['Offline',offline,'SSH unavailable','critical'],['Containers',containers.length,'From online hosts',''],['Healthy',containers.filter(c=>containerHealth(c)==='healthy'&&containerState(c)==='running').length,'Passing healthchecks','good'],['Need attention',problems,'Container problems',problems?'warning':'good']];const needs=findings(),recent=state.alerts.slice(-4).reverse();return heading('Infrastructure overview','A clear view of your servers, containers and what needs attention.',button('add-server','+ Add Server','','primary'))+`<div class="stats">${stats.map(([name,value,sub,kind])=>`<article class="stat"><div class="stat-label">${name}</div><div class="stat-value ${kind}">${value}</div><small>${sub}</small></article>`).join('')}</div>${state.busy?'<p class="form-note">Collecting fresh SSH snapshots. Hosts still being checked are not counted as offline.</p>':''}<div class="two-column"><section class="panel"><div class="section-head"><h2>Needs Attention ${needs.length?badge(needs.length+' items','warning'):''}</h2><a href="#alerts">View all →</a></div>${needs.length?needs.slice(0,4).map(attentionRow).join(''):`<div class="clear-state">${badge('All clear','good')} ${state.servers.length?'No priority warnings in collected snapshots.':'Add your first server to start monitoring.'}</div>`}</section><section class="panel"><div class="section-head"><h2>Recent Alerts</h2><a href="#alerts">View all →</a></div>${recent.length?recent.map(a=>attentionRow({id:a.id,title:a.guidance?.category||'Application error',server:{name:a.serverName},containerName:a.containerName,severity:'warning'})).join(''):'<div class="clear-state">No recent log errors detected.<p class="form-note">Log checks run every 90 seconds. Coverage and collection errors appear in Alerts.</p></div>'}</section></div><section><div class="section-head"><h2>Servers Overview <small>· ${state.servers.length} hosts</small></h2><a href="#servers">Manage servers →</a></div>${state.servers.length?`<div class="server-grid">${state.servers.slice(0,12).map(serverCard).join('')}</div>${state.servers.length>12?'<p class="form-note">Showing the first 12 hosts. Open Servers to search your entire infrastructure.</p>':''}`:`<div class="panel">${empty('Your infrastructure starts here','Connect a Linux server over SSH. No agent, extra service or external database required.',button('add-server','+ Connect your first server','','primary'))}</div>`}</section>`}
function option(value,label,selected){return `<option value="${esc(value)}"${selected===value?' selected':''}>${esc(label)}</option>`}
function filteredServers(){const f=state.filters.servers;return state.servers.filter(s=>(s.name+' '+s.host).toLowerCase().includes(f.search.toLowerCase())&&(f.tag==='all'||(f.tag==='none'?!(s.tags||[]).length:(s.tags||[]).includes(f.tag)))&&(f.status==='all'||statusFor(s)===f.status)).sort((a,b)=>f.sort==='status'?statusFor(a).localeCompare(statusFor(b))||a.name.localeCompare(b.name):f.sort==='cpu'?(state.snapshots.get(b.id)?.cpuPercent??-1)-(state.snapshots.get(a.id)?.cpuPercent??-1):a.name.localeCompare(b.name))}
function serverResults(){const servers=filteredServers();if(!servers.length)return empty('No servers found','Add a server or adjust the search and filters.',button('add-server','+ Add Server','','primary'));if(state.serverView==='cards')return `<div class="server-grid">${servers.map(serverCard).join('')}</div>`;return `<div class="table-wrap"><table class="responsive"><thead><tr><th>Server</th><th>Status</th><th>Tags</th><th>CPU</th><th>Memory</th><th>Actions</th></tr></thead><tbody>${servers.map(s=>{const snap=state.snapshots.get(s.id);return `<tr><td class="name-cell" data-label="Server"><b>${esc(s.name)}</b><small>${esc(s.host)}:${s.port}</small></td><td data-label="Status">${statusBadge(s)}</td><td data-label="Tags">${tagBadges(s)}</td><td data-label="CPU">${pct(snap?.online?snap.cpuPercent:null)}</td><td data-label="Memory">${pct(snap?.online?percent(snap.memoryUsed,snap.memoryTotal):null)}</td><td data-label="Actions"><div class="actions">${button('open-server','Open',s.id)}${button('edit-server','Edit',s.id,'quiet')}</div></td></tr>`}).join('')}</tbody></table></div>`}
function serversPage(){const f=state.filters.servers;return heading('Servers','Connect, organize and inspect your Linux hosts.',button('add-server','+ Add Server','','primary'))+`<div class="toolbar"><input aria-label="Search servers" data-filter="servers.search" placeholder="Search by name or IP…" value="${esc(f.search)}"><select aria-label="Filter servers by tag" data-filter="servers.tag">${option('all','All tags',f.tag)}${state.tags.map(t=>option(t.id,t.name,f.tag)).join('')}${option('none','Untagged',f.tag)}</select><select aria-label="Filter servers by status" data-filter="servers.status">${['all','online','offline','pending'].map(v=>option(v,v==='all'?'All statuses':v[0].toUpperCase()+v.slice(1),f.status)).join('')}</select><select aria-label="Sort servers" data-filter="servers.sort">${option('name','Name A–Z',f.sort)}${option('status','Connection status',f.sort)}${option('cpu','Highest CPU',f.sort)}</select><div class="view-switch">${button('view-cards','Cards','',state.serverView==='cards'?'active':'')}${button('view-list','List','',state.serverView==='list'?'active':'')}</div></div><div id="results">${serverResults()}</div>`}
function containersTable(items){if(!items.length)return empty('No containers to display','Try another filter. Docker metrics are collected only from connected hosts with Docker access.');return `<div class="table-wrap"><table class="responsive"><thead><tr><th>Container</th><th>Server</th><th>Status</th><th>Healthcheck</th><th>CPU</th><th>Memory</th><th>Network I/O</th><th>Actions</th></tr></thead><tbody>${items.map(c=>{const label=labelFor(c),health=containerHealth(c);return `<tr><td class="name-cell" data-label="Container"><b title="${esc(c.name)}">${esc(label.alias||c.name)}</b>${label.alias?`<small>${esc(c.name)}</small>`:''}${label.description?`<small>${esc(label.description)}</small>`:''}</td><td data-label="Server">${esc(c.server.name)}</td><td data-label="Status">${badge(containerState(c),containerProblem(c)?'critical':containerState(c)==='running'?'good':'')}</td><td data-label="Healthcheck">${badge(health,health==='healthy'?'good':health==='unhealthy'?'critical':health==='starting'?'warning':'')}</td><td data-label="CPU">${esc(c.cpu||'—')}</td><td data-label="Memory">${esc(c.memory||'—')}</td><td data-label="Network I/O">${esc(c.netIO||'—')}</td><td data-label="Actions"><div class="actions"><button data-action="container" data-id="${esc(c.id)}" data-server="${esc(c.server.id)}">Details</button><button class="quiet" data-action="logs" data-id="${esc(c.id)}" data-server="${esc(c.server.id)}">Logs</button></div></td></tr>`}).join('')}</tbody></table></div>`}
function containerResults(){const f=state.filters.containers;const list=allContainers().filter(c=>(c.name+' '+(labelFor(c).alias||'')).toLowerCase().includes(f.search.toLowerCase())&&(f.server==='all'||c.server.id===f.server)&&(f.status==='all'||f.status==='problem'&&containerProblem(c)||containerState(c)===f.status)).sort((a,b)=>f.sort==='cpu'?parseFloat(b.cpu||0)-parseFloat(a.cpu||0):f.sort==='memory'?memoryBytes(b.memory)-memoryBytes(a.memory):(labelFor(a).alias||a.name).localeCompare(labelFor(b).alias||b.name));return containersTable(list)}
function memoryBytes(text){const match=(text||'').match(/^([\d.]+)\s*([KMGT]?i?B)/i);if(!match)return 0;return Number(match[1])*1024**({B:0,KB:1,KIB:1,MB:2,MIB:2,GB:3,GIB:3,TB:4,TIB:4}[match[2].toUpperCase()]||0)}
function containersPage(){const f=state.filters.containers;return heading('Containers','Every Docker container, across your connected hosts.')+`<div class="toolbar"><input aria-label="Search containers" data-filter="containers.search" placeholder="Search Docker or friendly name…" value="${esc(f.search)}"><select aria-label="Filter containers by server" data-filter="containers.server">${option('all','All servers',f.server)}${state.servers.map(s=>option(s.id,s.name,f.server)).join('')}</select><select aria-label="Filter containers by status" data-filter="containers.status">${['all','running','problem','exited','restarting','paused','dead'].map(v=>option(v,v==='all'?'All statuses':v==='problem'?'Needs attention':v[0].toUpperCase()+v.slice(1),f.status)).join('')}</select><select aria-label="Sort containers" data-filter="containers.sort">${option('name','Name A–Z',f.sort)}${option('cpu','Highest CPU',f.sort)}${option('memory','Highest memory',f.sort)}</select></div><div id="results">${containerResults()}</div>`}
function tagsPage(){return heading('Tags & Groups','Organize servers by customer, cloud, environment or team.',button('add-tag','+ Create Tag','','primary'))+`<div class="notice">Assign up to 8 tags to each server. Tags organize your workspace and never modify a remote host.</div>${state.tags.length?`<div class="tag-grid">${state.tags.map(tag=>{const count=state.servers.filter(s=>(s.tags||[]).includes(tag.id)).length;return `<article class="tag-card" style="--tag-color:${palette[tag.color]}"><h3>${tagChip(tag)}</h3><p>${count} associated server${count===1?'':'s'}</p><div class="actions">${button('tag-servers','View servers',tag.id)}${button('edit-tag','Edit',tag.id,'quiet')}${button('delete-tag','Delete',tag.id,'quiet bad')}</div></article>`}).join('')}</div>`:`<div class="panel">${empty('Give your servers some context','Create a tag, choose its color and assign it from a server’s settings.',button('add-tag','+ Create your first tag','','primary'))}</div>`}`}
function alertsResults(){const f=state.filters.alerts;const rows=alertRows().filter(a=>(f.severity==='all'||a.severity===f.severity)&&(f.server==='all'||a.server.id===f.server)&&(f.source==='all'||a.source===f.source));return rows.length?`<div class="table-wrap"><table class="responsive"><thead><tr><th>Alert</th><th>Severity</th><th>Server</th><th>Origin</th><th>Collected</th><th>Actions</th></tr></thead><tbody>${rows.map(a=>`<tr><td class="name-cell"><b>${esc(a.title)}</b><small>${esc(a.containerName||a.evidence.slice(0,100))}</small></td><td data-label="Severity">${badge(a.severity,a.severity)}</td><td data-label="Server">${esc(a.server.name)}</td><td data-label="Origin">${a.source==='health'?'Health snapshot':'Container logs'}</td><td data-label="Collected">${esc(new Date(a.at).toLocaleString())}</td><td data-label="Actions">${button('finding','Details',a.id)}</td></tr>`).join('')}</tbody></table></div>`:empty('No matching alerts','Warnings appear here when a health snapshot or container log check detects a relevant problem.')}
function alertsPage(){const f=state.filters.alerts;const coverage=state.servers.map(s=>{const error=state.scanErrors[s.id];return `<div class="info-item"><small>${esc(s.name)}</small><strong class="${error?'warning':''}">${esc(error||state.coverage[s.id]||'Waiting for the next log scan')}</strong></div>`}).join('');return heading('Alerts','Health findings and recent log errors, with evidence and suggested checks.')+`<div class="toolbar"><select aria-label="Filter alert severity" data-filter="alerts.severity">${['all','critical','warning'].map(v=>option(v,v==='all'?'All severities':v[0].toUpperCase()+v.slice(1),f.severity)).join('')}</select><select aria-label="Filter alert server" data-filter="alerts.server">${option('all','All servers',f.server)}${state.servers.map(s=>option(s.id,s.name,f.server)).join('')}</select><select aria-label="Filter alert origin" data-filter="alerts.source">${option('all','All origins',f.source)}${option('health','Health snapshots',f.source)}${option('logs','Container logs',f.source)}</select></div><div id="results">${alertsResults()}</div><details class="panel"><summary>Log scan coverage · every 90 seconds</summary><p class="form-note">The latest 200 log errors are retained in memory. A clean exit or a container without a healthcheck is not automatically a failure. Offline means SSH collection failed; it does not prove the host is down.</p><div class="info-grid">${coverage||'<p class="muted">No servers registered.</p>'}</div></details>`}
function metricCard(label,value,sub='',valuePercent=null,kind=''){return `<article class="stat detail-metric"><div class="stat-label">${label}</div><div class="stat-value ${kind}">${esc(value)}</div><small>${esc(sub)}</small>${Number.isFinite(valuePercent)?bar(valuePercent,kind):''}</article>`}
function serverPage(){const s=state.servers.find(s=>s.id===state.serverId);if(!s)return heading('Server not found','This server may have been removed.')+button('go-servers','Back to Servers');const snap=state.snapshots.get(s.id),online=snap?.online;let body='';if(state.tab==='summary'){body=`${snap&&!online?`<div class="notice danger">${esc(snap.error||'SSH unavailable')}. Monitoring values are unavailable until the connection succeeds.</div>`:''}<div class="details-grid">${metricCard('CPU',pct(online?snap.cpuPercent:null),'Latest short sample',online?snap.cpuPercent:null)}${metricCard('Memory',pct(online?percent(snap.memoryUsed,snap.memoryTotal):null),online?human(snap.memoryUsed)+' / '+human(snap.memoryTotal):'Unavailable',online?percent(snap.memoryUsed,snap.memoryTotal):null,'cyan')}${metricCard('Root disk',pct(online?percent(snap.diskUsed,snap.diskTotal):null),online?human(snap.diskUsed)+' / '+human(snap.diskTotal):'Unavailable',online?percent(snap.diskUsed,snap.diskTotal):null,'green')}${metricCard('Network',online?snap.network:'—','One-second transfer rate')}${metricCard('Uptime',online?snap.uptime:'—','Reported by Linux')}${metricCard('Containers',online?(snap.containers||[]).length:'—',online?'Docker: '+(snap.dockerStatus||'unknown'):'Unavailable')}</div><section class="panel"><h2>Connection & load</h2><div class="info-grid">${info('Connection',statusFor(s))}${info('SSH address',s.user+'@'+s.host+':'+s.port)}${info('Load average',online?snap.load:'—')}${info('Last collected',snap?.at?new Date(snap.at).toLocaleString():'Pending')}</div></section><section class="panel"><h2>Relevant findings</h2>${findings().filter(f=>f.server.id===s.id).map(attentionRow).join('')||'<p class="clear-state">No priority findings in this snapshot.</p>'}</section>`}else if(state.tab==='containers'){body=containersTable(allContainers().filter(c=>c.server.id===s.id))}else if(state.tab==='diagnostics'){body=diagnosticPanel(s.id)}else if(state.tab==='logs'){body=logPanel(s.id)}else{body=`<section class="panel"><h2>Server configuration</h2><div class="info-grid">${info('Name',s.name)}${info('Host',s.host)}${info('SSH user / port',s.user+' · '+s.port)}${info('Authentication',s.authMethod||'Mounted SSH key')}</div><div class="tags">${tagsFor(s).map(tagChip).join('')}</div><div class="actions">${button('edit-server','Edit server',s.id,'primary')}${button('assign-tags','Edit tags',s.id)}${button('test-server','Test connection',s.id)}${button('remove-server','Remove server',s.id,'danger')}</div><p class="form-note">Connection edits are tested before saving. The trusted host key is retained and identity changes are rejected.</p></section>`}return heading(s.name,s.host+' · Dedicated server workspace',button('go-servers','← All servers'))+`<div class="actions">${statusBadge(s)}${tagBadges(s)}</div><div class="tabs" role="tablist" aria-label="Server details">${['summary','containers','logs','diagnostics','settings'].map(tab=>`<button role="tab" aria-selected="${state.tab===tab}" data-action="server-tab" data-id="${tab}" class="${state.tab===tab?'active':''}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div><div role="tabpanel">${body}</div>`}
function info(label,value){return `<div class="info-item"><small>${esc(label)}</small><strong>${esc(value??'—')}</strong></div>`}
function diagnosticPanel(id){return `<section class="panel"><h2>Read-only diagnostics</h2><p class="form-note">Collected only when requested. Commands and response sizes are limited. No remote data is changed.</p><div class="diag-buttons">${[['processes','Processes','Top CPU & memory users'],['storage','Storage','Filesystems & Docker usage'],['network','Network','Interfaces & connections'],['events','Docker events','Recent activity, last 30 min']].map(([view,title,sub])=>`<button data-action="diagnostic" data-id="${view}" data-server="${esc(id)}"><b>${title}</b><small>${sub}</small></button>`).join('')}</div><div id="diagOutput" class="diag-result"><p class="muted">Choose a diagnostic to collect its results.</p></div></section>`}
function diagnosticsPage(){return heading('Diagnostics','Investigate a server when you need more detail.')+`<div class="toolbar"><select id="diagnosticServer" aria-label="Diagnostic server">${option('','Choose a server','')}${state.servers.map(s=>option(s.id,s.name,'')).join('')}</select></div>${state.servers.length?diagnosticPanel(''):empty('Connect a server first','Diagnostics use the same trusted SSH connection as monitoring.')}`}
function logPanel(id){const containers=allContainers().filter(c=>c.server.id===id);return `<section class="panel"><h2>Container logs</h2><p class="form-note">Loads at most 200 recent lines on request. Log output may contain private information.</p><div class="log-tools"><select id="logContainer" aria-label="Choose container for logs">${containers.map(c=>option(c.id,labelFor(c).alias||c.name,'')).join('')}</select>${button('load-server-logs','Load logs',id,'primary')}</div><div id="serverLogs"></div></section>`}
function settingsPage(){return heading('Settings','Manage account access and optional notifications.')+`<div class="settings-layout"><section class="panel"><div class="setting-heading"><span class="account-icon">⚿</span><h2>Account</h2></div><p>Admin access stays local to this installation.</p><form id="passwordForm"><div class="form-grid"><label class="full">Current password<input type="password" name="currentPassword" autocomplete="current-password" required maxlength="256"></label><label>New password<input type="password" name="newPassword" autocomplete="new-password" minlength="14" maxlength="256" required></label><label>Confirm new password<input type="password" name="confirmPassword" autocomplete="new-password" minlength="14" maxlength="256" required></label></div><p class="form-note">At least 14 characters. Environment-managed credentials must be changed in the container configuration.</p><div class="form-error" role="alert" hidden></div><div class="form-actions"><button type="submit" class="primary">Update password</button></div></form></section><section class="panel"><div class="setting-heading"><span class="account-icon">↗</span><h2>Notifications</h2></div><p>Send optional log-error alerts to Telegram. Similar alerts share a cooldown.</p><form id="telegramForm"><label class="inline-check"><input type="checkbox" name="enabled">Enable Telegram notifications</label><div class="form-grid"><label class="full">Bot token<input type="password" name="token" autocomplete="new-password" placeholder="Paste token, or leave blank to retain it" maxlength="120"></label><label>Chat ID<input name="chatId" placeholder="123456789 or -100…" maxlength="25"></label><label>Cooldown (minutes)<input name="cooldownMinutes" type="number" min="5" max="1440" value="30" required></label></div><p id="tokenStatus" class="form-note">Loading saved settings…</p><p class="form-note">Create a bot with @BotFather, then start a conversation with it or add it to your group.</p><div class="form-error" role="alert" hidden></div><div class="form-actions">${button('test-telegram','Send test message')}<button type="submit" class="primary">Save notifications</button></div></form></section><section class="panel"><h2>General</h2><div class="info-grid">${info('Snapshot refresh','Every 30 seconds while visible')}${info('Log checks','Every 90 seconds')}${info('Remote actions','Read-only')}${info('Storage','Persistent local Docker volume')}</div><p class="form-note">Snapshots are shared for 25 seconds to avoid redundant SSH requests. Diagnostics and logs are requested on demand.</p></section></div>`}
function aboutPage(){const a=state.about;return heading('About ContScope','Open-source visibility for your Linux hosts and Docker containers.')+`<div class="two-column"><section class="panel"><img class="about-logo" src="/assets/contscope-mark.svg" alt="ContScope"><h2>Small footprint. Clear picture.</h2><p class="muted">One container, encrypted local credentials and no monitoring agents.</p><div class="info-grid">${info('Version',a.version||'Loading…')}${info('License','Apache 2.0')}${info('Commit',a.commit||'—')}${info('Build date',a.buildDate||'—')}</div><div class="about-links"><a href="https://github.com/ttavares369/ContScope" target="_blank" rel="noopener noreferrer">GitHub repository ↗</a><a href="https://github.com/ttavares369/ContScope/issues" target="_blank" rel="noopener noreferrer">Report an issue ↗</a></div><div class="help-item"><h3>Support this project</h3><p>Star the repository, report bugs or contribute improvements. Donations remain unavailable until a verified funding account is configured.</p></div></section><section class="panel"><h2>Get expert help · Jupiter TI</h2><p class="muted">Need help with Linux, Docker or your infrastructure? Prepare a report, review it and share it yourself.</p><div class="actions">${button('support','Prepare support report','','primary')}<a href="mailto:tiago@jupiterti.com">Contact Jupiter TI ↗</a></div><div class="help-item"><h3>SSH identity & first connection</h3><p>Connect & Add Server discovers the host key and trusts it on first use (TOFU). Independently verify your first connection through a trusted network or console. The key is pinned; subsequent changes are rejected, including when you edit credentials.</p></div><div class="help-item"><h3>Recover admin access</h3><p>The initial password is printed once in container logs. Reset it locally with:</p><pre class="code-output">docker compose exec contscope /usr/local/bin/contscope reset-admin</pre><p>Preserve and back up the complete data volume, including the encryption key. Use HTTPS or an SSH tunnel for remote access.</p></div></section></div>`}
function render(){const pages={overview,servers:serversPage,containers:containersPage,alerts:alertsPage,tags:tagsPage,server:serverPage,diagnostics:diagnosticsPage,settings:settingsPage,about:aboutPage};$('content').innerHTML=pages[state.route]();$('breadcrumb').textContent=names[state.route];document.querySelectorAll('#navigation a').forEach(a=>{const active=a.dataset.page===(state.route==='server'?'servers':state.route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('serverCount').textContent=state.servers.length;$('alertCount').textContent=alertRows().length;if(state.route==='settings')loadTelegram();}
function route(){const [page,id,tab]=location.hash.slice(1).split('/');state.route=Object.hasOwn(names,page)?page:'overview';state.serverId=id||'';state.tab=['summary','containers','logs','diagnostics','settings'].includes(tab)?tab:'summary';document.body.classList.remove('nav-open');$('navBackdrop').hidden=true;$('mobileNav').setAttribute('aria-expanded','false');render();}
function navigate(page){if(location.hash==='#'+page)route();else location.hash=page}
async function loadRegistry(){[state.servers,state.tags,state.labels]=await Promise.all([api('/api/servers'),api('/api/tags'),api('/api/labels')]);const ids=new Set(state.servers.map(s=>s.id));for(const id of state.snapshots.keys())if(!ids.has(id))state.snapshots.delete(id)}
async function loadAlerts(){const result=await api('/api/alerts');state.alerts=result.alerts||[];state.coverage=result.coverage||{};state.scanErrors=result.errors||{}}
function updateView(){if($('modal').open)return;if(['settings','diagnostics','tags','about'].includes(state.route))return;if(state.route==='server'&&['logs','diagnostics','settings'].includes(state.tab))return;if(['servers','containers','alerts'].includes(state.route)&&$('results')){const renderer={servers:serverResults,containers:containerResults,alerts:alertsResults};$('results').innerHTML=renderer[state.route]();$('alertCount').textContent=alertRows().length;return}render()}
async function refresh(){if(state.busy)return;state.busy=true;$('refresh').disabled=true;try{let index=0;await Promise.all(Array.from({length:Math.min(4,state.servers.length)},async()=>{while(index<state.servers.length){const s=state.servers[index++];try{const value=await api('/api/servers/'+encodeURIComponent(s.id));if(state.servers.some(v=>v.id===s.id))state.snapshots.set(s.id,value)}catch(error){state.snapshots.set(s.id,{server:s,online:false,error:error.message,findings:[{id:'ssh-'+s.id,title:'Snapshot unavailable',severity:'critical',evidence:error.message,nextStep:'Verify SSH connectivity and authentication.'}],containers:[],at:new Date().toISOString()})}}}));await loadAlerts();$('updated').textContent='Updated '+new Date().toLocaleTimeString();$('globalError').hidden=true;updateView()}catch(error){fail(error)}finally{state.busy=false;$('refresh').disabled=false;if(state.route==='overview'&&!$('modal').open)render()}}
function modal(title,body,wide=false){lastFocus=document.activeElement;modalEpoch++;$('modal').classList.toggle('wide',wide);$('modalTitle').textContent=title;$('modalBody').innerHTML=body;if(!$('modal').open)$('modal').showModal();return modalEpoch}
function closeModal(){modalEpoch++;$('modal').close();if(lastFocus?.isConnected)lastFocus.focus()}
function formError(form,error){const element=form.querySelector('.form-error');element.textContent=error.message||String(error);element.hidden=false}
async function submitForm(form,work){const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);const error=form.querySelector('.form-error');if(error)error.hidden=true;try{await work()}catch(e){if(error)formError(form,e);else throw e}finally{buttons.forEach(b=>b.disabled=false)}}
function serverModal(id=''){const server=state.servers.find(s=>s.id===id),edit=!!server;modal(edit?'Edit '+server.name:'Connect a server',`<p class="muted">${edit?'Leave the credential blank to keep it. Connection changes are tested before saving.':'Connect over SSH. ContScope discovers and pins the server identity automatically.'}</p><form id="serverForm" data-id="${esc(id)}"><div class="form-grid"><label>Server name<input name="name" value="${esc(server?.name||'')}" maxlength="64" pattern="[a-zA-Z0-9 _.-]{1,64}" placeholder="Production server" required></label><label>IP / hostname<input name="host" value="${esc(server?.host||'')}" maxlength="253" placeholder="192.0.2.10" required></label><label>SSH username<input name="user" value="${esc(server?.user||'')}" maxlength="64" placeholder="ubuntu" required></label><label>Authentication<select id="sshMode" name="authMethod">${edit&&!server.authMethod?option('','Mounted SSH key (keep)',''):''}${option('password','SSH password',edit?(server.authMethod||''):'password')}${option('key','Private key',edit?(server.authMethod||''):'password')}</select></label><label class="full" id="passwordLabel">SSH password<input name="password" type="password" autocomplete="new-password" maxlength="1024" ${!edit?'required':''}></label><label class="full" id="keyLabel" hidden>Private key<textarea name="privateKey" rows="5" placeholder="Paste an unencrypted SSH private key" maxlength="65536"></textarea><input type="file" id="keyFile" aria-label="Upload SSH private key"><p class="form-note">The key stays local and is encrypted at rest.</p></label></div><details ${edit?'open':''}><summary>Advanced options</summary><label>SSH port<input name="port" type="number" value="${server?.port||22}" min="1" max="65535" required></label></details><p class="form-note">${edit?'The trusted host key will be retained, including if the address changes.':'Trust on first use: verify your first connection independently. Later host key changes are rejected.'}</p><div class="form-error" role="alert" hidden></div><div class="form-actions">${button('cancel-modal','Cancel')}<button class="primary" type="submit">${edit?'Verify & Save Changes':'Connect & Add Server'}</button></div></form>`);authMode()}
function authMode(){const mode=$('sshMode').value,key=mode==='key',edit=!!$('serverForm').dataset.id;$('passwordLabel').hidden=key||mode==='';$('keyLabel').hidden=!key;$('serverForm').elements.password.required=!key&&!edit;$('serverForm').elements.privateKey.required=false}
function tagModal(id=''){const tag=state.tags.find(t=>t.id===id);modal(tag?'Edit tag':'Create a tag',`<form id="tagForm" data-id="${esc(id)}"><label>Tag name<input name="name" value="${esc(tag?.name||'')}" placeholder="Company A, Production, AWS…" maxlength="48" required autofocus></label><p class="form-note">Choose a name that helps identify a customer, cloud or environment.</p><label>Tag color</label><div class="color-options" role="radiogroup" aria-label="Tag color">${Object.entries(palette).map(([color,value])=>`<label class="color-choice" style="--tag-color:${value}" title="${color}"><input type="radio" name="color" value="${color}" aria-label="${color}" ${(tag?.color||'blue')===color?'checked':''}><span></span></label>`).join('')}</div><div class="form-error" role="alert" hidden></div><div class="form-actions">${button('cancel-modal','Cancel')}<button class="primary" type="submit">${tag?'Save Changes':'Create Tag'}</button></div></form>`)}
function assignModal(id){const server=state.servers.find(s=>s.id===id);if(!server)return;modal('Tags for '+server.name,`<form id="assignForm" data-id="${esc(id)}"><p class="muted">Select up to 8 tags for this server.</p>${state.tags.map(t=>`<label class="tag-check">${tagChip(t)}<input type="checkbox" name="tags" value="${esc(t.id)}" ${(server.tags||[]).includes(t.id)?'checked':''} aria-label="${esc(t.name)}"></label>`).join('')||'<p class="form-note">Create a tag from Tags & Groups first.</p>'}<div class="form-error" role="alert" hidden></div><div class="form-actions">${button('cancel-modal','Cancel')}<button type="submit" class="primary">Save Tags</button></div></form>`)}
function confirmation(title,message,action,id){modal(title,`<p class="muted">${esc(message)}</p><form id="confirmForm" data-action="${action}" data-id="${esc(id)}"><div class="form-error" role="alert" hidden></div><div class="form-actions">${button('cancel-modal','Cancel')}<button type="submit" class="danger">${action==='delete-tag'?'Delete Tag':'Remove Server'}</button></div></form>`)}
async function testServer(id,element){element.disabled=true;try{await api('/api/servers/'+encodeURIComponent(id)+'/test',{method:'POST'});toast('SSH connection succeeded')}catch(error){fail(error)}finally{element.disabled=false}}
async function diagnostic(server,view,container='',target='diagOutput'){const output=$(target);if(!server)throw new Error('Choose a server first.');output.innerHTML=loading('Collecting '+view+'…');try{const result=await api('/api/diagnostics?'+new URLSearchParams({server,view,container}));if(!output.isConnected)return;const rows=result.rows||[];output.innerHTML=`${result.notice?`<div class="notice warning">${esc(result.notice)}</div>`:''}<h3>${esc(view[0].toUpperCase()+view.slice(1))} <small>· ${esc(new Date(result.collected).toLocaleTimeString())}</small></h3>${rows.length?`<div class="table-wrap"><table class="responsive"><thead><tr>${Object.keys(rows[0]).map(key=>`<th>${esc(key)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${Object.keys(rows[0]).map(key=>`<td data-label="${esc(key)}">${esc(row[key]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No results returned','This diagnostic may be unavailable for the SSH account or have no recent activity.')}`}catch(error){if(output.isConnected)output.innerHTML=`<div class="notice danger">${esc(error.message)}</div>`}}
async function logsModal(server,container){const epoch=modal('Container logs',`<p class="form-note">Most recent 200 lines. Requested on demand.</p><div class="log-tools"><input id="logSearch" aria-label="Filter log lines" placeholder="Filter lines…">${button('reload-logs','Reload',container)}</div><pre id="logOutput" class="code-output">Loading logs…</pre>`,true);$('logOutput').dataset.server=server;$('logOutput').dataset.container=container;await fetchLogs(server,container,epoch)}
async function fetchLogs(server,container,epoch=modalEpoch){try{const result=await api('/api/logs?'+new URLSearchParams({server,container}));if(epoch!==modalEpoch||!$('logOutput'))return;$('logOutput').dataset.raw=(result.logs||'No logs returned')+(result.truncated?'\n[Output truncated]':'');filterLogs()}catch(error){if(epoch===modalEpoch&&$('logOutput'))$('logOutput').textContent=error.message}}
function filterLogs(){const output=$('logOutput');if(output)output.textContent=(output.dataset.raw||'').split('\n').filter(line=>line.toLowerCase().includes(($('logSearch')?.value||'').toLowerCase())).join('\n')||'No matching lines'}
async function containerModal(serverId,id){const c=allContainers().find(c=>c.server.id===serverId&&c.id===id);if(!c)return;const label=labelFor(c);modal(label.alias||c.name,`<div class="actions">${badge(containerState(c),containerProblem(c)?'critical':'good')}${badge(containerHealth(c))}<button data-action="logs" data-id="${esc(id)}" data-server="${esc(serverId)}">Open logs</button></div><p class="form-note">Docker name: ${esc(c.name)}</p><div id="containerInfo"></div><form id="labelForm" data-server="${esc(serverId)}" data-name="${esc(c.name)}"><h3>Local display name</h3><div class="form-grid"><label>Friendly name<input name="alias" value="${esc(label.alias||'')}" maxlength="64" placeholder="${esc(c.name)}"></label><label>Description<input name="description" value="${esc(label.description||'')}" maxlength="200"></label></div><p class="form-note">Presentation metadata only. Docker is never renamed. Leave both fields empty to remove the label.</p><div class="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary" type="submit">Save Display Name</button></div></form>`,true);await diagnostic(serverId,'container',id,'containerInfo')}
function findingModal(id){const f=alertRows().find(a=>a.id===id);if(!f)return;modal(f.title,`<div class="actions">${badge(f.severity,f.severity)}<span class="muted">${esc(f.server.name)}</span></div><div class="help-item"><h3>Evidence</h3><pre class="code-output">${esc(f.evidence)}</pre><h3>Suggested checks</h3><p>${esc(f.nextStep||'Inspect the connection and recent application logs.')}</p></div><div class="form-actions">${button('open-server','Open server',f.server.id)}${f.containerId?`<button class="primary" data-action="logs" data-id="${esc(f.containerId)}" data-server="${esc(f.server.id)}">View logs</button>`:''}${f.view&&f.view!=='logs'&&f.view!=='container'?`<button class="primary" data-action="finding-diag" data-id="${esc(f.view)}" data-server="${esc(f.server.id)}">Open ${esc(f.view)}</button>`:''}</div>`)}
async function loadTelegram(){const form=$('telegramForm');try{const result=await api('/api/telegram');if(!form.isConnected)return;form.elements.chatId.value=result.chatId||'';form.elements.cooldownMinutes.value=result.cooldownMinutes||30;form.elements.enabled.checked=!!result.enabled;$('tokenStatus').textContent=result.tokenConfigured?'Saved bot token is configured. Leave the token field blank to retain it.':'No bot token configured.'}catch(error){if(form.isConnected)formError(form,error)}}
async function telegramSubmit(form,test){return submitForm(form,async()=>{const data={enabled:form.elements.enabled.checked,chatId:form.elements.chatId.value.trim(),cooldownMinutes:Number(form.elements.cooldownMinutes.value),token:form.elements.token.value,test};await api('/api/telegram',{method:'POST',...json(data)});toast(test?'Telegram test delivered':'Notification settings saved');if(!test){form.elements.token.value='';await loadTelegram()}})}
function supportModal(){modal('Prepare a support report',`<p class="form-note">Nothing is sent automatically. Review redaction before exporting and sharing.</p><form id="supportForm"><label>Server<select name="serverId">${state.servers.map(s=>option(s.id,s.name,'')).join('')}</select></label><label class="inline-check"><input type="checkbox" name="includeLogExcerpts">Include recent error excerpts</label><div class="form-error" role="alert" hidden></div><button type="submit" class="primary">Prepare Report</button></form><label class="form-row">Review and edit<textarea id="supportReport" rows="10" placeholder="Prepare a report to review it here."></textarea></label><div class="actions"><button data-action="download-report" id="downloadReport" disabled>Download JSON</button><a href="mailto:tiago@jupiterti.com?subject=ContScope%20support">Compose email ↗</a></div><p class="form-note">Attach the exported report yourself. Check for private information that automated redaction may miss.</p>`,true)}
async function action(element){const {action,id,server}=element.dataset;switch(action){
 case 'add-server':serverModal();break;case 'edit-server':serverModal(id);break;case 'open-server':if($('modal').open)closeModal();navigate('server/'+id+'/summary');break;case 'go-servers':navigate('servers');break;
 case 'server-tab':navigate('server/'+state.serverId+'/'+id);break;case 'view-cards':case 'view-list':state.serverView=action==='view-cards'?'cards':'list';localStorage.setItem('contscope.serverView',state.serverView);render();break;
 case 'add-tag':tagModal();break;case 'edit-tag':tagModal(id);break;case 'delete-tag':{const tag=state.tags.find(t=>t.id===id);confirmation('Delete '+tag.name+'?','This removes the tag from every associated server. It does not remove any server.','delete-tag',id);break}
 case 'tag-servers':state.filters.servers.tag=id;navigate('servers');break;case 'assign-tags':assignModal(id);break;case 'remove-server':confirmation('Remove server?','Monitoring will stop and its saved SSH credential will be removed. The remote server and containers will remain untouched.','remove-server',id);break;
 case 'test-server':await testServer(id,element);break;case 'cancel-modal':closeModal();break;case 'finding':findingModal(id);break;
 case 'diagnostic':element.disabled=true;try{await diagnostic(server||$('diagnosticServer')?.value,id)}finally{element.disabled=false}break;
 case 'finding-diag':closeModal();navigate('server/'+server+'/diagnostics');setTimeout(()=>diagnostic(server,id),0);break;
 case 'logs':await logsModal(server,id);break;case 'reload-logs':{const output=$('logOutput');await fetchLogs(output.dataset.server,output.dataset.container);break}
 case 'load-server-logs':{const container=$('logContainer').value;if(!container)throw new Error('No container selected');await logsModal(id,container);break}
 case 'container':await containerModal(server,id);break;case 'test-telegram':await telegramSubmit($('telegramForm'),true);break;case 'support':supportModal();break;
 case 'download-report':{const text=$('supportReport').value;JSON.parse(text);const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='contscope-support-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}
}}
document.addEventListener('click',event=>{const element=event.target.closest('button[data-action]');if(element&&!element.disabled)action(element).catch(fail)});
document.addEventListener('input',event=>{const element=event.target;if(element.dataset.filter){const [page,key]=element.dataset.filter.split('.');state.filters[page][key]=element.value;const fn={servers:serverResults,containers:containerResults,alerts:alertsResults};$('results').innerHTML=fn[page]()}if(element.id==='logSearch')filterLogs();if(element.id==='supportReport')$('downloadReport').disabled=!element.value.trim()});
document.addEventListener('change',event=>{if(event.target.id==='sshMode')authMode();if(event.target.id==='keyFile'){const file=event.target.files[0];if(file){if(file.size>65536){formError($('serverForm'),new Error('Private key file is too large'));return}file.text().then(text=>$('serverForm').elements.privateKey.value=text).catch(fail)}}});
document.addEventListener('submit',event=>{const form=event.target;if(!['serverForm','tagForm','assignForm','confirmForm','labelForm','passwordForm','telegramForm','supportForm'].includes(form.id))return;event.preventDefault();submitForm(form,async()=>{const data=Object.fromEntries(new FormData(form));switch(form.id){
 case 'serverForm':{const edit=!!form.dataset.id;const payload={name:data.name.trim(),host:data.host.trim(),user:data.user.trim(),port:Number(data.port),authMethod:data.authMethod,secret:data.authMethod==='key'?data.privateKey:data.password};await api(edit?'/api/servers/'+encodeURIComponent(form.dataset.id):'/api/servers/quick',{method:edit?'PATCH':'POST',...json(payload)});closeModal();await loadRegistry();toast(edit?'Server configuration saved':'Server connected and added');render();await refresh();break}
 case 'tagForm':await api('/api/tags',{method:form.dataset.id?'PATCH':'POST',...json({...data,...(form.dataset.id?{id:form.dataset.id}:{}),name:data.name.trim()})});closeModal();await loadRegistry();render();toast('Tag saved');break;
 case 'assignForm':await api('/api/tags/assign',{method:'PUT',...json({serverId:form.dataset.id,tags:new FormData(form).getAll('tags')})});closeModal();await loadRegistry();render();toast('Server tags saved');break;
 case 'confirmForm':if(form.dataset.action==='delete-tag'){await api('/api/tags',{method:'DELETE',...json({id:form.dataset.id})});if(state.filters.servers.tag===form.dataset.id)state.filters.servers.tag='all';toast('Tag deleted')}else{await api('/api/servers/'+encodeURIComponent(form.dataset.id),{method:'DELETE'});toast('Server removed');navigate('servers')}closeModal();await loadRegistry();render();break;
 case 'labelForm':await api('/api/labels',{method:'POST',...json({...data,serverId:form.dataset.server,containerName:form.dataset.name})});state.labels=await api('/api/labels');closeModal();render();toast('Display name saved');break;
 case 'passwordForm':if(data.newPassword!==data.confirmPassword)throw new Error('New passwords do not match');await api('/api/admin/password',{method:'POST',...json(data)});form.reset();toast('Password changed. Sign in again using the new password.');break;
 case 'telegramForm':await telegramSubmit(form,false);break;
 case 'supportForm':{if(!data.serverId)throw new Error('Add a server first');const result=await api('/api/support/report',{method:'POST',...json({serverId:data.serverId,includeLogExcerpts:form.elements.includeLogExcerpts.checked})});$('supportReport').value=JSON.stringify(result,null,2);$('downloadReport').disabled=false;toast('Report prepared locally. Review before sharing.');break}
 }}).catch(fail)});
$('closeModal').onclick=closeModal;$('modal').addEventListener('cancel',event=>{event.preventDefault();closeModal()});
$('refresh').onclick=()=>refresh();$('collapseNav').onclick=()=>{document.body.classList.toggle('collapsed');$('collapseNav').setAttribute('aria-label',document.body.classList.contains('collapsed')?'Expand sidebar':'Collapse sidebar');localStorage.setItem('contscope.collapsed',document.body.classList.contains('collapsed')?'1':'0')};
$('mobileNav').onclick=()=>{const open=document.body.classList.toggle('nav-open');$('navBackdrop').hidden=!open;$('mobileNav').setAttribute('aria-expanded',String(open));if(open)document.querySelector('#navigation a.active')?.focus()};
$('navBackdrop').onclick=()=>{document.body.classList.remove('nav-open');$('navBackdrop').hidden=true;$('mobileNav').setAttribute('aria-expanded','false');$('mobileNav').focus()};
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('nav-open'))$('navBackdrop').click();const tab=event.target.closest('[role=tab]');if(tab&&['ArrowRight','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();const tabs=[...tab.parentElement.querySelectorAll('[role=tab]')],index=tabs.indexOf(tab),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();setTimeout(()=>document.querySelector(`[role=tab][data-id="${tabs[next].dataset.id}"]`)?.focus(),0)}});
window.addEventListener('hashchange',route);
if(localStorage.getItem('contscope.collapsed')==='1')document.body.classList.add('collapsed');
(async()=>{try{await loadRegistry();await loadAlerts();state.about=await api('/api/about');$('footerVersion').textContent='· '+state.about.version;route();await refresh()}catch(error){fail(error);$('content').innerHTML=empty('Unable to load workspace','Reload the page after checking your authentication and data volume.')}})();
setInterval(()=>{if(!document.hidden)refresh()},30000);
